package com.servicehub.api;
import com.servicehub.domain.*; import com.servicehub.repository.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/requests") public class ServiceRequestController { private final RequestRepository requests; private final UserRepository users; public ServiceRequestController(RequestRepository r,UserRepository u){requests=r;users=u;} @GetMapping public List<RequestDtos.View> all(){return requests.findAllByOrderByUpdatedAtDesc().stream().map(RequestDtos.View::from).toList();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public RequestDtos.View create(@Valid @RequestBody RequestDtos.Create data,@AuthenticationPrincipal AppUser user){ServiceRequest r=new ServiceRequest();r.setReference("SR-"+(1000+requests.count()+1));r.setTitle(data.title());r.setDescription(data.description());r.setCategory(data.category());r.setPriority(data.priority()==null?"Medium":data.priority());r.setCustomer(user);return RequestDtos.View.from(requests.save(r));} @PatchMapping("/{id}") public RequestDtos.View update(@PathVariable UUID id,@RequestBody RequestDtos.Update data){ServiceRequest r=requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(data.status()!=null)r.setStatus(data.status());if(data.assigneeId()!=null)r.setAssignee(users.findById(data.assigneeId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Employee not found")));return RequestDtos.View.from(requests.save(r));} }
